<?php
$e = static fn (mixed $value): string => htmlspecialchars((string) $value, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');
$money = static fn (mixed $value): string => number_format((float) $value, 2, ',', '.') . ' €';
$date = static fn (mixed $value): string => $value ? date('d/m/Y', strtotime((string) $value)) : '—';
$address = static function (array $party) use ($e): string {
    $city = trim(($party['postal_code'] ?? '') . ' ' . ($party['city'] ?? '') . ' ' . (!empty($party['province']) ? '(' . $party['province'] . ')' : ''));
    return $e($party['address'] ?? '') . ($city !== '' ? '<br>' . $e($city) : '') . '<br>' . $e($party['country_code'] ?? 'IT');
};
?>
