<table class="top"><tr><td><h1><?= $e($definition['singular']) ?> <?= $e($document['number']) ?></h1><div class="doc-meta"><strong>Data:</strong> <?= $date($document['document_date']) ?><br><strong>Valuta:</strong> <?= $e($document['currency'] ?: 'EUR') ?><?php if (!empty($document['fatturapa_type'])): ?><br><strong>Tipo FatturaPA:</strong> <?= $e($document['fatturapa_type']) ?><?php endif; ?></div></td><td class="issuer"><strong><?= $e($organization['business_name'] ?? '') ?></strong><br><?= $address($organization) ?><br>P.IVA <?= $e($organization['vat_number'] ?? '—') ?> · C.F. <?= $e($organization['tax_code'] ?? '—') ?><br>Regime fiscale <?= $e($organization['fiscal_regime'] ?? '—') ?><br><?php if (!empty($organization['sdi_code'])): ?>SDI <?= $e($organization['sdi_code']) ?> · <?php endif; ?><?= $e($organization['pec'] ?? $organization['email'] ?? '') ?><br><?php if (!empty($organization['phone'])): ?>Tel. <?= $e($organization['phone']) ?><?php endif; ?></td></tr></table>
