<table class="lines"><thead><tr><th>#</th><th>Codice / descrizione</th><th class="right">Q.tà</th><th>U.M.</th><th class="right">Prezzo</th><th class="right">Sc. %</th><th class="right">Imponibile</th><th class="right">IVA</th><th class="right">Totale</th></tr></thead><tbody><?php foreach ($lines as $line): ?><tr><td><?= (int) $line['line_number'] ?></td><td><?php if (!empty($line['product_code'])): ?><strong><?= $e($line['product_code']) ?></strong><br><?php endif; ?><?= $e($line['description']) ?><?php if (!empty($line['vat_nature'])): ?><br><span class="muted">Natura <?= $e($line['vat_nature']) ?></span><?php endif; ?></td><td class="right"><?= number_format((float) $line['quantity'], 2, ',', '.') ?></td><td><?= $e($line['unit'] ?: 'NR') ?></td><td class="right nowrap"><?= $money($line['unit_price']) ?></td><td class="right"><?= number_format((float) $line['discount_percent'], 2, ',', '.') ?></td><td class="right nowrap"><?= $money($line['taxable_amount']) ?></td><td class="right"><?= number_format((float) $line['vat_rate'], 2, ',', '.') ?>%</td><td class="right nowrap"><?= $money($line['total_amount']) ?></td></tr><?php endforeach; ?></tbody></table>
<table class="summary"><tr><td style="width:50%;padding-right:18px"><h2>Pagamento</h2><strong><?= $e($document['payment_terms_label'] ?? 'Condizioni non specificate') ?></strong><br>Modalità: <?= $e($document['payment_method_code'] ?? '—') ?><br>Scadenza: <?= $date($document['due_date']) ?><?php if (!empty($document['bank_name']) || !empty($document['bank_iban'])): ?><br>Banca: <?= $e($document['bank_name'] ?? '') ?><?php if (!empty($document['bank_abi'])): ?> · ABI <?= $e($document['bank_abi']) ?><?php endif; ?><?php if (!empty($document['bank_cab'])): ?> · CAB <?= $e($document['bank_cab']) ?><?php endif; ?><?php if (!empty($document['bank_iban'])): ?><br>IBAN <?= $e($document['bank_iban']) ?><?php endif; ?><?php endif; ?></td><td style="width:50%"><table class="totals"><tr><td>Imponibile</td><td class="right"><?= $money($document['taxable_total']) ?></td></tr><tr><td>IVA</td><td class="right"><?= $money($document['vat_total']) ?></td></tr><?php if ((float) $document['stamp_duty_total'] > 0): ?><tr><td>Bollo</td><td class="right"><?= $money($document['stamp_duty_total']) ?></td></tr><?php endif; ?><?php if ((float) $document['withholding_total'] > 0): ?><tr><td>Ritenuta <?= number_format((float) $document['withholding_rate'], 2, ',', '.') ?>%</td><td class="right">− <?= $money($document['withholding_total']) ?></td></tr><?php endif; ?><tr class="grand"><td>Totale documento</td><td class="right"><?= $money($document['total']) ?></td></tr><tr><td><strong>Netto da pagare</strong></td><td class="right"><strong><?= $money($document['balance_due']) ?></strong></td></tr></table></td></tr></table>
